&lt;div id=&quot;56$309493-input-168668d6e8b00136-input&quot; class=&quot;WLWX WOWX WF-X WG-X WKUX WNWX WC5 WMWX&quot; data-automation-id=&quot;richTextEditor&quot; data-no-h=&quot;true&quot; data-metadata-id=&quot;56$309493&quot; data-uxi-widget-editable=&quot;false&quot; data-uxi-form-item-parent-active-list-id=&quot;6$63848&quot; data-uxi-form-item-child-list-index=&quot;3&quot; data-uxi-form-item-moniker-iid=&quot;219$350&quot;&gt;
